import json, glob, os, jsonlines

def main():
    path = '/home/cielo_1/projects/my_agent/artifacts/terminal_bench_jsonl_aggregator'
    user_totals = {}
    tag_counts = {}
    total_records = 0
    for fpath in glob.glob(os.path.join(path, 'records_*.jsonl')):
        with jsonlines.jsonlines(fpath) as reader:
            for record in reader:
                total_records += 1
                user = record.get('user', 'unknown')
                amount = float(record.get('amount', 0.0))
                items = record.get('items', [])
                tags = record.get('tags', [])
                user_totals[user] = {'amount': user_totals.get(user, {'amount': 0.0})['amount'] + amount, 'items': user_totals.get(user, {'items': []})['items'] + items}
                for tag in tags:
                    tag_counts[tag] = tag_counts.get(tag, 0) + 1
    top_users = sorted([(u, round(d['amount'], 2)), d['items']] for u, d in user_totals.items(), key=lambda x: (-x[0], x[1][0]))[:5]
    top_tags = sorted(tag_counts.items(), key=lambda x: (-x[1], x[0]))[:5]
    with open(os.path.join(path, 'aggregates.json'), 'w') as f:
        json.dump({
            'total_records': total_records,
            'top_5_users_by_amount': [f'{u} ({amt})' for u, amt in top_users],
            'top_5_tags_by_count': [f'{tag} ({count})' for tag, count in top_tags]
        }, f)
if __name__ == '__main__':
    main()

